@Serializable data class UserDto(val id: Long, val name: String)

interface UserApi {
  @GET("users/{id}")
  suspend fun getUser(@Path("id") id: Long): UserDto
}

val logging = HttpLoggingInterceptor().apply {
  level = if (BuildConfig.DEBUG) HttpLoggingInterceptor.Level.BODY else HttpLoggingInterceptor.Level.NONE
  redactHeader("Authorization")
}

// One client for the whole app — it owns the connection pool
val client = OkHttpClient.Builder()
  .addInterceptor(logging)
  .addInterceptor { chain ->
    val req = chain.request().newBuilder()
      .addHeader("Accept", "application/json")
      .build()
    chain.proceed(req)
  }
  .connectTimeout(10, TimeUnit.SECONDS)
  .readTimeout(15, TimeUnit.SECONDS)
  .build()

val json = Json { ignoreUnknownKeys = true }

val retrofit = Retrofit.Builder()
  .baseUrl("https://api.example.com/")
  .client(client)
  .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
  .build()

val userApi: UserApi = retrofit.create()

suspend fun load(): UserDto = userApi.getUser(42)   // suspends, runs on OkHttp's pool

