sealed class AppError(message: String? = null) : Throwable(message) {
  object NetworkUnavailable : AppError()
  data class Server(val code: Int, val payload: String?) : AppError("HTTP $code")
  data class NotAuthorized(override val cause: Throwable? = null) : AppError("401")
  data class Contract(override val cause: Throwable) : AppError(cause.message)
  data class Unknown(override val cause: Throwable) : AppError(cause.message)
}

suspend fun <T> safeApi(block: suspend () -> T): Result<T> = try {
  Result.success(block())
} catch (e: HttpException) {
  val body = e.response()?.errorBody()?.string()
  Result.failure(
    if (e.code() == 401) AppError.NotAuthorized(e) else AppError.Server(e.code(), body)
  )
} catch (e: IOException) {
  Result.failure(AppError.NetworkUnavailable)
} catch (e: SerializationException) {
  Result.failure(AppError.Contract(e))
} catch (e: Throwable) {
  Result.failure(AppError.Unknown(e))
}

// Repository maps wire errors to domain errors exactly once
class UserRepository(private val api: UserApi) {
  suspend fun getUser(id: Long): Result<User> = safeApi { api.getUser(id).toDomain() }
}

// ViewModel never sees HttpException
viewModelScope.launch {
  userRepository.getUser(id)
    .onSuccess { user -> _state.update { it.copy(user = user, error = null) } }
    .onFailure { e -> _state.update { it.copy(error = e.toUiMessage()) } }
}

