val cacheDir = File(context.cacheDir, "http").apply { mkdirs() }
val cache = Cache(directory = cacheDir, maxSize = 50L * 1024 * 1024)   // 50 MB

// Servers don't always send a useful Cache-Control — rewrite it on the way in
val rewriteCache = Interceptor { chain ->
  chain.proceed(chain.request()).newBuilder()
    .header("Cache-Control", "public, max-age=300")
    .removeHeader("Pragma")
    .build()
}

// Offline: serve from cache instead of failing
val offlineFallback = Interceptor { chain ->
  val request = if (!isNetworkAvailable(context)) {
    chain.request().newBuilder()
      .cacheControl(
        CacheControl.Builder().onlyIfCached().maxStale(7, TimeUnit.DAYS).build()
      )
      .build()
  } else chain.request()
  chain.proceed(request)
}

val client = OkHttpClient.Builder()
  .cache(cache)
  .addInterceptor(offlineFallback)        // application interceptor
  .addNetworkInterceptor(rewriteCache)    // once per network round trip
  .build()

