interface UploadApi {
  @Multipart
  @POST("upload")
  suspend fun upload(
    @Part("name") name: RequestBody,
    @Part file: MultipartBody.Part
  )
}

suspend fun upload(api: UploadApi, file: File, name: String) {
  val body = file.asRequestBody("image/jpeg".toMediaTypeOrNull())   // streamed, not buffered
  val part = MultipartBody.Part.createFormData("avatar", file.name, body)
  api.upload(name.toRequestBody("text/plain".toMediaTypeOrNull()), part)
}

// Progress — wrap the RequestBody and count what goes into the sink
class ProgressBody(
  private val delegate: RequestBody,
  private val onProgress: (sent: Long, total: Long) -> Unit
) : RequestBody() {
  override fun contentType() = delegate.contentType()
  override fun contentLength() = delegate.contentLength()

  override fun writeTo(sink: BufferedSink) {
    val total = contentLength()
    val counting = object : ForwardingSink(sink) {
      var sent = 0L
      override fun write(source: Buffer, byteCount: Long) {
        super.write(source, byteCount)
        sent += byteCount
        onProgress(sent, total)        // fires per 8 KB segment — throttle downstream
      }
    }.buffer()
    delegate.writeTo(counting)
    counting.flush()
  }
}

// Survive the app being backgrounded: WorkManager owns the retry policy
class UploadWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
  override suspend fun doWork(): Result = try {
    upload(api, File(inputData.getString("path")!!), "avatar")
    Result.success()
  } catch (e: IOException) {
    Result.retry()
  }
}

// Socket as a Flow: opened on collect, closed when the collector goes away
fun OkHttpClient.messages(url: String): Flow<String> = callbackFlow {
  val listener = object : WebSocketListener() {
    override fun onMessage(ws: WebSocket, text: String) { trySend(text) }
    override fun onClosed(ws: WebSocket, code: Int, reason: String) { close() }
    override fun onFailure(ws: WebSocket, t: Throwable, r: Response?) { close(t) }
  }
  val socket = newWebSocket(Request.Builder().url(url).build(), listener)
  awaitClose { socket.close(1000, "collector gone") }
}

// Reconnect with capped exponential backoff
fun Flow<String>.withReconnect(): Flow<String> = retryWhen { cause, attempt ->
  if (cause !is IOException) return@retryWhen false
  delay(minOf(30_000L, 1000L shl attempt.toInt().coerceAtMost(5)))
  true
}

// Collected from the UI — stops at STOPPED, so the socket closes with the screen
class ChatViewModel(client: OkHttpClient) : ViewModel() {
  val messages: StateFlow<List<String>> = client.messages(WS_URL)
    .withReconnect()
    .runningFold(emptyList<String>()) { acc, msg -> acc + msg }
    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())
}

